// energy/degradation sketch for: Circular Manufacturing Simulator
let c = 1.0; const samples = [];
for (let i = 0; i < 520; i++) { c *= 0.99951; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 520, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

